import java.io.*;

public class Main {
    static byte[] buf;
    static int len = 0, p = 0;

    static int nextInt() {
        while (p < len && (buf[p] < '0' || buf[p] > '9') && buf[p] != '-') p++;
        int s = 1;
        if (p < len && buf[p] == '-') { s = -1; p++; }
        int x = 0;
        while (p < len && buf[p] >= '0' && buf[p] <= '9') {
            x = x * 10 + (buf[p] - '0');
            p++;
        }
        return x * s;
    }

    public static void main(String[] args) throws IOException {
        ByteArrayOutputStream bos = new ByteArrayOutputStream(1 << 22);
        byte[] chunk = new byte[1 << 16];
        int r;
        DataInputStream in = new DataInputStream(new BufferedInputStream(System.in, 1 << 16));
        while ((r = in.read(chunk)) > 0) bos.write(chunk, 0, r);
        buf = bos.toByteArray();
        len = buf.length;

        int n = nextInt();
        int[] mArr = new int[n + 1];
        int[] off = new int[n + 1];
        int total = 0;
        for (int i = 1; i <= n; i++) {
            off[i] = total;
            int m = nextInt();
            mArr[i] = m;
            total += m;
        }
        int[] data = new int[total];
        for (int i = 1; i <= n; i++) {
            int st = off[i];
            for (int j = 0; j < mArr[i]; j++) {
                data[st + j] = nextInt();
            }
        }

        int[] color = new int[n + 1]; // 0 = nao visitado, 1 = time 1, 2 = time 2
        int[] queue = new int[n];
        int head = 0, tail = 0;

        color[1] = 1;
        queue[tail++] = 1;

        while (head < tail) {
            int u = queue[head++];
            int c = color[u];
            int st = off[u], en = st + mArr[u];
            for (int j = st; j < en; j++) {
                int v = data[j];
                if (v == u) continue;      // ignora "nao gosta de si mesmo"
                if (color[v] == 0) {
                    color[v] = 3 - c;
                    queue[tail++] = v;
                }
            }
        }

        // componentes desconectados (caso existam): menor aluno ainda sem time vai para o time 1
        for (int i = 2; i <= n; i++) {
            if (color[i] != 0) continue;
            color[i] = 1;
            queue[tail++] = i;
            head = tail - 1;
            while (head < tail) {
                int u = queue[head++];
                int c = color[u];
                int st = off[u], en = st + mArr[u];
                for (int j = st; j < en; j++) {
                    int v = data[j];
                    if (v == u) continue;
                    if (color[v] == 0) {
                        color[v] = 3 - c;
                        queue[tail++] = v;
                    }
                }
            }
        }

        StringBuilder l1 = new StringBuilder();
        StringBuilder l2 = new StringBuilder();
        for (int i = 1; i <= n; i++) {
            if (color[i] == 1) l1.append(i).append(' ');
            else l2.append(i).append(' ');
        }
        if (l1.length() > 0) l1.setLength(l1.length() - 1);
        if (l2.length() > 0) l2.setLength(l2.length() - 1);

        PrintStream out = new PrintStream(new BufferedOutputStream(System.out, 1 << 20));
        out.println(l1.toString());
        out.println(l2.toString());
        out.flush();
    }
}
